import{_ as t,o as r,c as a,aN as s}from"./chunks/framework.D31DlcCL.js";const e="/img/edu-openclaw-3-1.svg",n="/img/edu-openclaw-3-2.svg",g="/img/edu-openclaw-3-3.svg",l="/img/edu-openclaw-3-4.svg",c="/img/edu-openclaw-3-5.svg",i="/img/edu-openclaw-3-6.svg",p="/img/edu-openclaw-3-7.svg",d="/img/edu-openclaw-3-8.svg",w=JSON.parse('{"title":"小学生教程③：一键生成“故事绘本”发班级群","description":"","frontmatter":{"title":"小学生教程③：一键生成“故事绘本”发班级群","date":"2026-02-28T20:20:00.000Z","categories":["杂谈"],"tags":["小学生教程","OpenClaw","小作家养成记"]},"headers":[],"relativePath":"posts/openclaw-edu-3.md","filePath":"posts/openclaw-edu-3.md","lastUpdated":null}'),u={name:"posts/openclaw-edu-3.md"};function h(m,o,_,b,q,k){return r(),a("div",null,[...o[0]||(o[0]=[s('<h1 id="小学生教程3-一键生成-故事绘本-发班级群" tabindex="-1">小学生教程③：一键生成“故事绘本”发班级群 <a class="header-anchor" href="#小学生教程3-一键生成-故事绘本-发班级群" aria-label="Permalink to &quot;小学生教程③：一键生成“故事绘本”发班级群&quot;">​</a></h1><p>嘿！想不想当个<strong>受人崇拜的小作家</strong>？✍️ 写作文太枯燥？想画画又怕画不好？ 别担心！你的“魔法同桌”小螃蟹（OpenClaw） 能帮你<strong>分分钟做出一本精美的故事绘本</strong>！📚</p><p>它不仅能帮你<strong>想情节</strong>， 还能帮你<strong>画出超级漂亮的插图</strong>！ 快跟着我，让你的故事在班级群里<strong>火起来</strong>：</p><h3 id="🧠-第一步-开启你的-脑洞开关" tabindex="-1">🧠 第一步：开启你的“脑洞开关” <a class="header-anchor" href="#🧠-第一步-开启你的-脑洞开关" aria-label="Permalink to &quot;🧠 第一步：开启你的“脑洞开关”&quot;">​</a></h3><p>想一想你的故事里有谁？在哪里？发生了什么？ 比如：<strong>“一只爱吃披萨的猫，坐着火箭去火星！”</strong> 🐱🍕🚀 只要几个关键词，就能点亮灵感！</p><blockquote><p><img src="'+e+'" alt="图片1：小朋友头顶冒出一个大大的彩色灯泡，里面有小猫、披萨、火箭"><strong>图注：想出你的关键词，这就是故事的“种子”！🌱</strong></p></blockquote><h3 id="💬-第二步-告诉小螃蟹你的主意" tabindex="-1">💬 第二步：告诉小螃蟹你的主意 <a class="header-anchor" href="#💬-第二步-告诉小螃蟹你的主意" aria-label="Permalink to &quot;💬 第二步：告诉小螃蟹你的主意&quot;">​</a></h3><p>在聊天框里给小螃蟹发： <strong>“帮我写一个爱吃披萨的小猫去火星的故事！”</strong> 🪐 一定要把它当成你的好朋友，好好商量哦！</p><blockquote><p><img src="'+n+'" alt="图片2：在电脑屏幕上打字，小螃蟹在旁边拼命点头"><strong>图注：告诉它你的主意，它马上就开始“写写写”啦！✍️</strong></p></blockquote><h3 id="📖-第三步-故事大王开讲啦" tabindex="-1">📖 第三步：故事大王开讲啦！ <a class="header-anchor" href="#📖-第三步-故事大王开讲啦" aria-label="Permalink to &quot;📖 第三步：故事大王开讲啦！&quot;">​</a></h3><p>你会看到一段<strong>超级精彩的故事</strong>瞬间出现了！ 不仅有惊险的冒险，还有<strong>搞笑的对话</strong>！ 如果你觉得不够酷，还可以让它改一改！</p><blockquote><p><img src="'+g+'" alt="图片3：屏幕上像瀑布一样流出文字，伴随着小星星"><strong>图注：哇！故事写得太棒了，简直像电影剧本！🎬</strong></p></blockquote><h3 id="🎨-第四步-变身-小小插画师" tabindex="-1">🎨 第四步：变身“小小插画师” <a class="header-anchor" href="#🎨-第四步-变身-小小插画师" aria-label="Permalink to &quot;🎨 第四步：变身“小小插画师”&quot;">​</a></h3><p>对小螃蟹说：<strong>“给我的故事配上超酷的绘本插图！”</strong> 🎨 你可以要求它画成<strong>动画片风格、水彩画风格</strong>或者<strong>油画风格</strong>！</p><blockquote><p><img src="'+l+'" alt="图片4：小螃蟹手里拿着好几支画笔，在空中飞舞"><strong>图注：它正在挑选最漂亮的画笔，为你绘制独一无二的插画！🖌️</strong></p></blockquote><h3 id="✨-第五步-奇迹发生啦" tabindex="-1">✨ 第五步：奇迹发生啦！ <a class="header-anchor" href="#✨-第五步-奇迹发生啦" aria-label="Permalink to &quot;✨ 第五步：奇迹发生啦！&quot;">​</a></h3><p>一张又一张<strong>漂亮的插图</strong>跳了出来！ 有在宇宙飞船里啃披萨的猫，还有<strong>橘红色的火星沙漠</strong>！🌈 每一张都能直接拿来当壁纸！</p><blockquote><p><img src="'+c+'" alt="图片5：一幅幅精美的宇宙猫插画在屏幕上展示"><strong>图注：看！你的故事现在变得有声有色，太真实啦！🎇</strong></p></blockquote><h3 id="📋-第六步-排版你的-个人作品集" tabindex="-1">📋 第六步：排版你的“个人作品集” <a class="header-anchor" href="#📋-第六步-排版你的-个人作品集" aria-label="Permalink to &quot;📋 第六步：排版你的“个人作品集”&quot;">​</a></h3><p>小螃蟹会帮你把文字和图片<strong>排得整整齐齐</strong>， 就像在书店里买到的<strong>正式绘本</strong>一样！📖 甚至还能给你的书起一个响亮的名字！</p><blockquote><p><img src="'+i+'" alt="图片6：一张完整的绘本页面预览，左边是图右边是字"><strong>图注：现在的你，已经是一名真正的“大作家”啦！🤴</strong></p></blockquote><h3 id="📤-第七步-一键分享-全班围观" tabindex="-1">📤 第七步：一键分享，全班围观 <a class="header-anchor" href="#📤-第七步-一键分享-全班围观" aria-label="Permalink to &quot;📤 第七步：一键分享，全班围观&quot;">​</a></h3><p>点一下**“分享”<strong>按钮，选你的</strong>班级群**！📤 把你做好的绘本发出去， 让大家看看你的<strong>超级创意</strong>！</p><blockquote><p><img src="'+p+'" alt="图片7：点一下“分享”箭头，绘本飞进了群聊窗口"><strong>图注：把你的才华分享给大家，准备迎接掌声吧！👏</strong></p></blockquote><h3 id="🏆-第八步-收获满满的赞" tabindex="-1">🏆 第八步：收获满满的赞！ <a class="header-anchor" href="#🏆-第八步-收获满满的赞" aria-label="Permalink to &quot;🏆 第八步：收获满满的赞！&quot;">​</a></h3><p>群里的小伙伴们一定会疯狂给你<strong>点赞和发表情包</strong>！❤️ 老师也会夸你是个<strong>科技小达人</strong>！ 这种感觉是不是<strong>爽翻了</strong>？</p><blockquote><p><img src="'+d+'" alt="图片8：群里跳出无数个红心、大拇指和夸奖的话"><strong>图注：分享的快乐最无敌！和小螃蟹一起加油吧！✨</strong></p></blockquote><hr><h3 id="🎁-本课小挑战" tabindex="-1">🎁 本课小挑战 <a class="header-anchor" href="#🎁-本课小挑战" aria-label="Permalink to &quot;🎁 本课小挑战&quot;">​</a></h3><p><strong>第一关：</strong> 让小螃蟹讲一个“橡皮擦大作战”的故事，并配一张图！ <strong>第二关：</strong> 把你的故事发到朋友圈或群里，看看能拿到多少个赞？ <strong>打卡方式：</strong> 把你的故事名字写在下面，看看谁的故事最脑洞大开！🌌</p>',30)])])}const P=t(u,[["render",h]]);export{w as __pageData,P as default};
